def patch_test(t):
    add = '''
test("restarting the process resets the in-memory roster", async () => {
  const before = (await call("/api/courses")).data.length;
  assert.equal((await call("/api/courses", "POST", { ...valid, code: "restart-1" })).status, 201);
  assert.equal((await call("/api/courses")).data.length, before + 1);
  await h.close();
  h = await application();
  assert.equal((await call("/api/courses")).data.length, before, "a fresh process seeds from scratch");
});
'''
    return t.rstrip('\n') + '\n' + add
